//
//  InkIcons.swift
//  Rescriva (fork of Open Scanner)
//
//  Rescriva's icons look pen-drawn: every icon at a given size has the same
//  stroke weight, ends are cut square with a slight flare where the pen
//  lifts, and corners are mitred. `Glyph` draws Rescriva's ink icon for an SF
//  Symbol name when there is one (InkIconPaths.swift, generated by
//  Tools/InkIcons/generate.py) and the SF Symbol otherwise.
//

import SwiftUI

/// The end of an open stroke on the 24-pt grid, and the direction it leaves in.
struct InkTerminal {
	let x: CGFloat
	let y: CGFloat
	let dx: CGFloat
	let dy: CGFloat
}

extension InkIcon {
	/// The stroke weight of an icon shown at `size` (an SF Symbol point size):
	/// the same for every icon, so a row of them reads as one pen.
	static func lineWidth(for size: CGFloat) -> CGFloat {
		max(1.25, size * 0.078)
	}

	/// The flares at the ends of open strokes, for strokes `width` grid units
	/// wide: a little wider than the stroke where the pen lifts, and a touch
	/// lopsided, like a nib held at an angle.
	func nibs(width: CGFloat) -> Path {
		var path = Path()
		for end in terminals {
			// Where the flare starts (back along the stroke) and where it ends (past the square cap)…
			let inner = CGPoint(x: end.x - end.dx * 0.45 * width, y: end.y - end.dy * 0.45 * width)
			let outer = CGPoint(x: end.x + end.dx * 0.5 * width, y: end.y + end.dy * 0.5 * width)
			// …and its half-widths either side of the stroke, across it.
			let across = CGVector(dx: -end.dy * width, dy: end.dx * width)
			let half: CGFloat = 0.5, left: CGFloat = 0.64, right: CGFloat = 0.58
			path.addLines([
				CGPoint(x: inner.x + across.dx * half, y: inner.y + across.dy * half),
				CGPoint(x: outer.x + across.dx * left, y: outer.y + across.dy * left),
				CGPoint(x: outer.x - across.dx * right, y: outer.y - across.dy * right),
				CGPoint(x: inner.x - across.dx * half, y: inner.y - across.dy * half),
			])
			path.closeSubpath()
		}
		return path
	}
}

/// One of Rescriva's ink icons, sized like an SF Symbol at `size` points and
/// drawn in the current foreground style. It has no accessibility of its own:
/// `Glyph` gives it the SF Symbol's.
struct InkGlyph: View {
	let icon: InkIcon
	var size: CGFloat = 17
	/// Fills the closed strokes too, for the `.fill` symbols (a starred star).
	var filled = false

	var body: some View {
		let box = size * 1.2
		let scale = box / 24
		let width = InkIcon.lineWidth(for: size)
		let toBox = CGAffineTransform(scaleX: scale, y: scale)
		ZStack {
			if filled {
				icon.strokes.applying(toBox).fill()
			}
			icon.strokes.applying(toBox)
				.stroke(style: StrokeStyle(lineWidth: width, lineCap: .square, lineJoin: .miter, miterLimit: 4))
			icon.marks.applying(toBox).fill()
			icon.nibs(width: width / scale).applying(toBox).fill()
		}
		.frame(width: box, height: box)
	}
}

/// An icon by SF Symbol name: Rescriva's ink version when there is one, the SF
/// Symbol otherwise. To VoiceOver an ink version is the SF Symbol it stands in
/// for, so it reads (or stays silent) exactly as the symbol would.
struct Glyph: View {
	let name: String
	var size: CGFloat
	var weight: Font.Weight

	init(_ name: String, size: CGFloat = 17, weight: Font.Weight = .regular) {
		self.name = name
		self.size = size
		self.weight = weight
	}

	var body: some View {
		if let icon = InkIcon(symbol: name) {
			InkGlyph(icon: icon, size: size, filled: name.hasSuffix(".fill"))
				.accessibilityRepresentation {
					Image(systemName: name)
				}
		} else {
			Image(systemName: name)
				.font(.system(size: size, weight: weight))
		}
	}
}
